from itertools import combinations
from random import Random
import re

LETTERS = "ABCDE"
SMALL_CASES = (
    (100, 100, 100, 100, 100),
    (2718, 2718, 2718, 2718, 2718),
    (100, 100, 100, 200, 300),
    (100, 100, 101, 2717, 2718),
    (128, 256, 512, 1024, 2048),
    (400, 500, 600, 700, 800),
    (800, 800, 900, 900, 1000),
    (2714, 2715, 2716, 2717, 2718),
)


def _parse(inp: str) -> tuple[int, ...] | None:
    tokens = inp.split()
    if len(tokens) != 5:
        return None
    values = []
    for token in tokens:
        if re.fullmatch(r"[+]?[0-9]+", token) is None:
            return None
        digits = token.lstrip("+").lstrip("0")
        if not 3 <= len(digits) <= 4:
            return None
        values.append(int(digits))
    a, b, c, d, e = values
    if not 100 <= a <= b <= c <= d <= e <= 2718:
        return None
    return tuple(values)


def validate_input(inp: str) -> bool:
    return _parse(inp) is not None


def _format(values) -> str:
    return " ".join(map(str, values)) + "\n"


def gen_small(seed: int, n: int) -> list[str]:
    rng = Random(seed)
    cases = []
    for i in range(n):
        if i < len(SMALL_CASES):
            values = SMALL_CASES[i]
        elif i % 3 == 0:
            unit = rng.randint(100, 453)
            values = sorted(unit * rng.randint(1, 6) for _ in LETTERS)
        elif i % 3 == 1:
            base = rng.randint(100, 2714)
            values = sorted(base + rng.randint(0, 4) for _ in LETTERS)
        else:
            values = sorted(rng.randint(100, 2718) for _ in LETTERS)
        cases.append(_format(values))
    return cases


def gen_stress(seed: int) -> list[str]:
    rng = Random(seed)
    unit = rng.randint(100, 110)
    return [
        _format((2718, 2718, 2718, 2718, 2718)),
        _format((unit, unit, 2 * unit, 4 * unit, 2718)),
    ]


def _names() -> tuple[str, ...]:
    return tuple(
        "".join(letters)
        for length in range(1, 6)
        for letters in combinations(LETTERS, length)
    )


def _score(name: str, values: tuple[int, ...]) -> int:
    return sum(values[LETTERS.index(letter)] for letter in name)


def check_postconditions(inp: str, out: str) -> list[tuple[str, str]]:
    values = _parse(inp)
    if values is None:
        return [("POST-6", "Input does not satisfy the stated preconditions.")]

    text = out.replace("\r\n", "\n")
    if text.endswith("\n"):
        text = text[:-1]
    lines = text.split("\n")
    if len(lines) != 31:
        return [("POST-1", f"Expected 31 lines, found {len(lines)}.")]
    if any(re.fullmatch(r"[A-Z]+", line) is None for line in lines):
        return [("POST-1", "Each line must contain one uppercase name.")]

    if set(lines) != set(_names()):
        return [("POST-2", "The lines must contain each legal name exactly once.")]

    failures = []
    scores = [_score(name, values) for name in lines]
    for i in range(30):
        if scores[i] < scores[i + 1]:
            failures.append(
                ("POST-3", f"Score increases from line {i + 1} to line {i + 2}.")
            )
        elif scores[i] == scores[i + 1] and lines[i] > lines[i + 1]:
            failures.append(
                ("POST-4", f"Tied names on lines {i + 1} and {i + 2} are reversed.")
            )
    return failures


def metamorphic_pairs(seed: int, n: int) -> list[tuple[str, str, str, str]]:
    rng = Random(seed)
    pairs = []
    for i in range(n):
        factor = rng.randint(2, 27)
        ceiling = 2718 // factor
        if i % 2 == 0:
            values = sorted(rng.randint(100, ceiling) for _ in LETTERS)
        else:
            values = [rng.randint(100, ceiling)] * 5
        scaled = [factor * value for value in values]
        pairs.append(("POST-5", "equal", _format(values), _format(scaled)))
    return pairs


def reference_small(inp: str) -> str | None:
    values = _parse(inp)
    if values is None:
        return None

    entries = [(name, _score(name, values)) for name in _names()]
    ranked = []
    for name, score in entries:
        rank = 1 + sum(
            other_score > score or (other_score == score and other_name < name)
            for other_name, other_score in entries
        )
        ranked.append((rank, name))
    return "".join(
        name + "\n"
        for position in range(1, 32)
        for rank, name in ranked
        if rank == position
    )
